import os,re,json,itertools
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def find_plus_centers(g):
    H,W=len(g),len(g[0])
    cells=set((r,c) for r in range(H) for c in range(W) if g[r][c]==2)
    out=[]
    # plus centers: bg cell with all 4 orthogonal neighbors == 2
    for r in range(1,H-1):
        for c in range(1,W-1):
            if g[r][c]==0 and all(0<g[rr][cc]<H or True for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]) :
                pass
    # simpler: scan for bg cell whose 4 orth neighbors are all 2
    res=[]
    for r in range(1,H-1):
        for c in range(1,W-1):
            if g[r][c]==0 and g[r-1][c]==2 and g[r+1][c]==2 and g[r][c-1]==2 and g[r][c+1]==2:
