import itertools
def solve(g):
    cs=find_plus_centers(g)
    out=[r[:] for r in g]
    cells=set((r,c) for r in range(len(g)) for c in range(len(g[0])) if g[r][c]==2)
    for a,b in itertools.combinations(cs,2):
        if a[0]==b[0]: rng=range(min(a[1],b[1])+1,max(a[1],b[1]))
        elif a[1]==b[1]: rng=range(min(a[0],b[0])+1,max(a[0],b[0]))
        else: continue
        for t in rng:
            p=(a[0],t) if a[0]==b[0] else (t,a[1])
            if p not in cells and out[p[0]][p[1]]==0: out[p[0]][p[1]]=1
    return out
